INSERT INTO products (id, name, slug, description, price, old_price, discount, category_id, brand, stock, sku, rating, reviews_count, image, is_active, is_featured, is_new, specifications) VALUES ('a47b3da1-bb9e-cc97-fde2-5c47aab19c37', 'Orient OpenHeart Automatic Sapphire', 'orient-openheart-automatic-sapphire', 'Orient OpenHeart — ochiq yurak mexanizmli zamonaviy hashamatli soat. Shaffof darcha orqali yapon mexanizmi harakati ko''rinib turadi. Tirnalishga chidamli sapfir shisha (Sapphire Crystal), oq siferblat, soniya hisoblagich sub-diali, tabiiy qora charm tasma. 2 yil rasmiy kafolat bilan.', 3920000, 4450000, 12, '118dee4b-db4d-e74d-7eeb-2264e986b373', 'Orient', 5, 'ORT-OPENHEART-WHT', 5, 8, '/products/orient_open_heart_white.png', true, false, true, '{"Korpus o''lchami":"40.8 mm","Korpus materiali":"Zanglamas po''lat 316L","Mexanizm":"Orient Cal. F6S22 Avtomatik (Yaponiya)","Shisha turi":"Sapfir shisha (Sapphire Crystal)","Tasma":"Tabiiy qora charm","Xususiyat":"Open Heart (Ochiq balans g''ildiragi)","Suvga chidamlilik":"50 metr / 5 BAR","Kafolat":"2 yil rasmiy kafolat"}'::jsonb) ON CONFLICT (id) DO NOTHING;
